/* Every word sits in an inline-block mask that crops it (overflow: clip, which is not a scroll
   container, so the view timeline still works). The padding and the equal negative margin give
   ascenders and descenders room under the very tight leading without changing the layout. The
   mask, not the moving word, is the view timeline, so the words of one line share their timing
   and the line rises as one, the way the original's split lines do. */
.kononenkogroup-lines-mask {
  display: inline-block;
  overflow: clip;
  vertical-align: baseline;
  /* text-indent is inherited: only the paragraph's first line is indented, not every word */
  text-indent: 0;
  padding-block: 0.2em 0.25em;
  margin-block: -0.2em -0.25em;
  view-timeline-name: --kononenkogroup-lines;
}

.kononenkogroup-lines-word {
  display: inline-block;
}

@media (prefers-reduced-motion: no-preference) {
  /* first screen: rise once on load */
  .kononenkogroup-lines[data-trigger="load"] .kononenkogroup-lines-word {
    animation: kononenkogroup-lines-rise 1.1s cubic-bezier(0.17, 0.84, 0.44, 1) both;
    animation-delay: var(--kononenkogroup-lines-delay, 0ms);
  }

  /* further down: rise as the line comes up from the bottom of the window, over a fixed 200px
     of scrolling (so a line already in view at load is simply there) */
  @supports (animation-timeline: view()) {
    .kononenkogroup-lines[data-trigger="scroll"] .kononenkogroup-lines-word {
      animation: kononenkogroup-lines-rise cubic-bezier(0.17, 0.84, 0.44, 1) both;
      animation-timeline: --kononenkogroup-lines;
      animation-range: entry 0px entry 200px;
    }
  }
}

@keyframes kononenkogroup-lines-rise {
  from {
    /* its own height plus the mask's padding: fully out of sight below the line */
    transform: translateY(calc(100% + 0.5em));
  }
  to {
    transform: none;
  }
}

import { Fragment, type CSSProperties, type ElementType } from "react";
import { cn } from "@foundry/foundry-utils";
import "./kononenkogroup-lines.css";

export interface KononenkogroupLinesProps {
  /** the text, split into words that each rise from their own mask; pass a list to force
      line breaks (each item becomes its own line) */
  text: string | string[];
  /** the element to render: p by default */
  as?: ElementType;
  /** "scroll": words rise as they come into view (CSS scroll-driven); "load": they rise once
      when the page loads, for text in the first screen */
  trigger?: "scroll" | "load";
  /** load only: delay before the rise, in ms */
  delay?: number;
  className?: string;
}

function Words({ text }: { text: string }) {
  const words = text.split(/\s+/).filter(Boolean);
  return (
    <>
      {words.map((word, i) => (
        <Fragment key={i}>
          <span className="kononenkogroup-lines-mask">
            <span className="kononenkogroup-lines-word">{word}</span>
          </span>
          {i < words.length - 1 && " "}
        </Fragment>
      ))}
    </>
  );
}

/**
 * Text whose lines rise into place from behind their own masks, the way every line of the
 * original moves. CSS only: without scroll-driven animations, or with reduced motion, the text
 * simply stands.
 */
export function KononenkogroupLines({ text, as: Tag = "p", trigger = "scroll", delay = 0, className }: KononenkogroupLinesProps) {
  return (
    <Tag
      data-trigger={trigger}
      className={cn("kononenkogroup-lines", className)}
      style={delay ? ({ "--kononenkogroup-lines-delay": `${delay}ms` } as CSSProperties) : undefined}
    >
      {Array.isArray(text)
        ? text.map((line, i) => (
            <span key={i} className="block">
              <Words text={line} />
            </span>
          ))
        : <Words text={text} />}
    </Tag>
  );
}
